SELECT CASE WHEN quantity >= 196 THEN 'high' WHEN quantity >= 92 THEN 'mid' ELSE 'low' END AS quantity_bucket, YEAR(last_restock) AS last_restock_year, MIN(last_restock) AS min_last_restock, MAX(quantity) AS max_quantity, MAX(last_restock) AS last_last_restock FROM inventory WHERE YEAR(last_restock) = 2025 GROUP BY ROLLUP(CASE WHEN quantity >= 196 THEN 'high' WHEN quantity >= 92 THEN 'mid' ELSE 'low' END, YEAR(last_restock))
